describe('account-number rules', () => {
  it('accepts a valid IBAN and rejects a transposed one — mod-97, not a length check', () => {
    expect(validateField('GB82WEST12345698765432', { valueType: 'iban' as never })).toBeNull();
    expect(validateField('GB82 WEST 1234 5698 7654 32', { valueType: 'iban' as never })).toBeNull();
    // two characters swapped: same length, same prefix, wrong checksum
    expect(validateField('GB82WEST12345698765423', { valueType: 'iban' as never })).toBeTruthy();
    expect(validateField('not-an-iban', { valueType: 'iban' as never })).toBeTruthy();
    expect(validateField('GB', { valueType: 'iban' as never })).toBeTruthy();
  });
  it('accepts a Luhn-valid card number and rejects a mistyped digit', () => {
    expect(validateField('4111111111111111', { valueType: 'card' as never })).toBeNull();
    expect(validateField('4111 1111 1111 1111', { valueType: 'card' as never })).toBeNull();
    expect(validateField('4111111111111112', { valueType: 'card' as never })).toBeTruthy();
    expect(validateField('abcd', { valueType: 'card' as never })).toBeTruthy();
  });
});

