describe('route guard', () => {
  afterEach(async () => { await clearSession(); });
  function mount(el: React.ReactElement) {
    let tree!: renderer.ReactTestRenderer;
    act(() => { tree = renderer.create(<NavigationContainer>{el}</NavigationContainer>); });
    return { json: () => JSON.stringify(tree.toJSON() ?? null), unmount: () => act(() => tree.unmount()) };
  }
  it('reports the session state through the provider', () => {
    let seen: { signedIn: boolean } | null = null;
    const Probe = () => { seen = useAuth(); return <Text>probe</Text>; };
    const m = mount(<AuthProvider><Probe /></AuthProvider>);
    expect(seen!.signedIn).toBe(false);
    m.unmount();
  });
  it('shows the fallback while signed out and the content once signed in', async () => {
    const out = mount(
      <AuthProvider><RequireAuth fallback={<Text>sign in</Text>}><Text>secret</Text></RequireAuth></AuthProvider>,
    );
    expect(out.json()).toContain('sign in');
    expect(out.json()).not.toContain('secret');
    out.unmount();
    await act(async () => { await setSession('token'); });
    const inn = mount(
      <AuthProvider><RequireAuth fallback={<Text>sign in</Text>}><Text>secret</Text></RequireAuth></AuthProvider>,
    );
    expect(inn.json()).toContain('secret');
    inn.unmount();
  });
  it('renders nothing when signed out and no fallback was given', () => {
    const m = mount(<AuthProvider><RequireAuth><Text>secret</Text></RequireAuth></AuthProvider>);
    expect(m.json()).not.toContain('secret');
    m.unmount();
  });
});
